<script setup lang="ts">
import { LoaderCircle } from 'lucide-vue-next'
import { reactive, ref } from 'vue'
import AuthLayout from '@/layouts/AuthLayout.vue'
import { authService } from '@/services/auth.service'
import { useToastStore } from '@/stores/toast.store'
import { getErrorMessage } from '@/utils/formatters'
import { registerSchema } from '@/validations/auth.schemas'
const form=reactive({nombre:'',apellido:'',email:'',password:''});const errors=ref<Record<string,string>>({});const busy=ref(false);const sent=ref(false);const toast=useToastStore()
async function submit(){const result=registerSchema.safeParse(form);if(!result.success){errors.value=Object.fromEntries(result.error.issues.map(i=>[String(i.path[0]),i.message]));return}busy.value=true;try{await authService.signUp(form.email,form.password,form.nombre,form.apellido);sent.value=true;toast.show('Cuenta creada','Revisa tu correo para confirmar el registro.','success')}catch(e){toast.show('No se pudo crear la cuenta',getErrorMessage(e),'error')}finally{busy.value=false}}
</script>
<template><AuthLayout><div v-if="sent" class="card border-brand-100 bg-brand-50 p-6 text-center"><h1 class="text-2xl font-bold text-ink">Revisa tu correo</h1><p class="mt-2 text-slate-600">Enviamos un enlace de confirmación a <strong>{{ form.email }}</strong>.</p><RouterLink to="/ingresar" class="btn-primary mt-6">Volver al ingreso</RouterLink></div><template v-else><h1 class="text-3xl font-bold text-ink">Crea tu cuenta</h1><p class="mt-2 text-slate-500">Compra y consulta tus pedidos desde cualquier lugar.</p><form class="mt-7 space-y-4" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-2"><div><label class="label">Nombre</label><input v-model="form.nombre" class="field" autocomplete="given-name"><p v-if="errors.nombre" class="mt-1 text-sm text-red-600">{{errors.nombre}}</p></div><div><label class="label">Apellido</label><input v-model="form.apellido" class="field" autocomplete="family-name"><p v-if="errors.apellido" class="mt-1 text-sm text-red-600">{{errors.apellido}}</p></div></div><div><label class="label">Correo</label><input v-model="form.email" class="field" type="email" autocomplete="email"><p v-if="errors.email" class="mt-1 text-sm text-red-600">{{errors.email}}</p></div><div><label class="label">Contraseña</label><input v-model="form.password" class="field" type="password" autocomplete="new-password"><p v-if="errors.password" class="mt-1 text-sm text-red-600">{{errors.password}}</p></div><button class="btn-primary w-full" :disabled="busy"><LoaderCircle v-if="busy" class="size-5 animate-spin"/>Crear cuenta</button></form><p class="mt-6 text-center text-slate-500">¿Ya tienes cuenta? <RouterLink to="/ingresar" class="font-semibold text-brand-700">Ingresar</RouterLink></p></template></AuthLayout></template>
